import Foundation

extension HelpContent {
    static let screensSection = HelpSection(id: "screens", title: "Screens", articles: [
        HelpArticle(
            id: "screen-overview",
            title: "Overview",
            summary: "What each card shows and which ones follow the date range.",
            blocks: [
                .paragraph("Overview is a dashboard. The **Period**, **Compare** and **Metric** controls at the top (see [Date range, comparison and Metric](help://concepts-metric-compare)) drive the cards marked “range” below; the others always look at fixed windows or all of your history. Press ⌘R to recompute it from local data. The **Share** button at the top right makes a recap card of the period and totals shown ([Sharing](help://screen-sharing))."),
                .table(headers: ["Card", "Follows the range?", "What it shows"], rows: [
                    ["**Milestone / Album turned over banners**", "No", "Dismissible notices from the last sync(s): [milestones](help://metrics-milestones) crossed and albums that completed a [turnover cycle](help://metrics-turnover)."],
                    ["**Almost there**", "No", "Up to 6 artists, albums or tracks exactly one play from a milestone, soonest expected first, in three columns and two rows. A narrower window shows the first 4 (two columns) or 2 (one column), never a third row."],
                    ["**Listening totals**", "Yes", "Scrobbles (or Time listened), distinct artists, albums and tracks in the range, each with a change badge against the comparison. The Tracks tile’s second line says how many of those tracks are loved right now. “N new” on Artists = artists whose first-ever play is in the range. “N turned over” on Albums = completions in the range."],
                    ["**Top picks**", "Yes", "The top artist, album and track by the Metric, each with a small trend line."],
                    ["**Last 24 hours**", "No", "Hourly plays over a rolling day. Click an hour that has plays to open that hour in [Query](help://query-basics) (each play of that day in that clock hour, newest first). The current hour can include plays from the same hour yesterday in its count, since the strip covers a rolling 24 hours; Query counts only today’s."],
                    ["**Current streak**", "No", "[Streaks](help://metrics-streaks-heatmap) with a 30-day strip. Click a day that has plays to open that day in [Query](help://query-basics), each play listed newest first."],
                    ["**On This Day**", "No", "Tracks you played on today’s date in earlier years."],
                    ["**Milestones**", "No", "Three random upcoming milestones."],
                    ["**Album Turnovers**", "No", "Albums a track or two from a completed cycle (needs Last.fm credentials)."],
                    ["**Most Recent, Most Often**", "No", "[New discoveries you play a lot](help://metrics-velocity) (90-day window, at least 5 plays)."],
                    ["**Climbing**", "No", "Tracks that broke into your top 500 in the last 90 days ([The Climb](help://metrics-climb))."],
                    ["**Fading Favorites**", "Yes", "[Tracks that peaked and went quiet](help://metrics-fading)."],
                    ["**Similar Sounds**", "No", "One artist, one album and one track from your library similar to what you played in the last 14 days ([how](help://metrics-similar))."],
                    ["**The Long Tail**", "Yes", "How concentrated your listening is ([Long tail](help://metrics-distribution))."],
                    ["**Top Tags**", "Yes (always plays)", "Your most-played tags, from artists’ community tags, ignoring the Metric switch."],
                    ["**Most recent**", "Yes", "Your last 10 scrobbles in the range with chart rank, previous rank and movement ([columns](help://metrics-chart-columns)). “View all” opens the full scrobble history."],
                ]),
                .paragraph("Cards that pick **3 random** items re-draw each time Overview loads from a fixed pool of qualifying items. Clicking a card opens the related screen or tool."),
            ]
        ),
        HelpArticle(
            id: "screen-top-charts",
            title: "Top Charts",
            summary: "Ranked lists of artists, albums or tracks, with movement against an earlier chart.",
            blocks: [
                .paragraph("Choose **Artists / Albums / Tracks**, the Period, Compare and Metric, and how many **Rows** (10 to 500, remembered per kind). The columns **This, Prev, Move, Peak** are defined in [Top Charts columns](help://metrics-chart-columns). Albums credited to several artists are merged into one row (see [Names, albums and artists](help://concepts-identity))."),
                .bullets([
                    "A **diamond** beside a row is [popularity](help://metrics-popularity); a heart on a track is loved.",
                    "**Right-click** a row for actions: open, love/unlove (needs Track Actions), flag, Fix Album Match, Resync, refresh/copy/paste/set/reset image, View Lyrics, View in Apple Music, View in Last.fm.",
                    "**Create Apple Music Playlist** exports the chart’s tracks that are in your Music library.",
                    "**Chart race** animates cumulative rankings across the range.",
                    "List or grid layout is a toggle.",
                    "**Share** makes an image or text of the chart as it is on screen ([Sharing](help://screen-sharing)).",
                ]),
            ]
        ),
        HelpArticle(
            id: "screen-weather",
            title: "Weather",
            summary: "Match your listening with the weather at home: rainy-day, snowy-day and hot-day music.",
            blocks: [
                .paragraph("**Settings › Weather** adds the weather at the time of each play to [Query](help://query-basics) and [Ask](help://ask). Ask “which songs do I play most when it rains?” or build it yourself with the weather fields. It is off until you turn it on."),
                .bullets([
                    "**Where:** choose a home place by searching for a city, or enter its coordinates. Weather is looked up for that place unless you add a trip (below). Coordinates are rounded to one decimal place (about 11 km).",
                    "**Trips:** trips live in **Tools › [Trips](help://tool-trips)**, which works with or without weather: record where you were and when, and see what you listened to on each. With weather on, press **I’m Away Now…** (the trip stays open until you press **Back Home**) or **Add a Trip…** for days in the past or ahead, choose the place (a city search, or a place you’ve used before), the first day and the last day. For those days every play looks up the weather where you were instead of at home. A place you only typed a name for has no weather. Nothing about your scrobbles is edited, so there is no need to touch past plays: add or change a trip and everything (Query fields, Trends, the plays list) follows. A trip’s weather is downloaded for just its dates. Where two trips overlap, the one that began later wins; trips that share days are highlighted in orange. Hot and cold stay relative to your home climate, so a hot trip really is hot for you.",
                    "**What:** hourly weather for the years your scrobbles span, from the free [Open-Meteo](https://open-meteo.com/) service (data under CC BY 4.0). Each play gets the weather of the hour it was made in. The last week or so comes from a quick-look source, whose values can differ from the settled archive by a few degrees; each update replaces those hours with the archive’s values as soon as it has them.",
                    "**Celsius or Fahrenheit:** Settings › Weather chooses the unit temperatures are shown and typed in (Automatic follows your Mac’s region). The weather itself is kept in Celsius, so changing it never alters your data.",
                    "**Hot and cold are relative.** *Cold* is the coldest 20% of hours at your place and *Hot* the warmest 20% (you can change both percentages), because 15° is warm in one climate and cold in another. Settings shows the temperatures this comes to for you.",
                ]),
                .paragraph("The fields, all in the Context group: **Weather** (the kind of weather most plays were made in), **Temperature (relative)** (Cold, Mild or Hot), **Average temperature when played**, **Share of plays in weather** (for example the share made in rain) and **Weather lift** (how much more or less than usual it is played in that weather, so a favourite that only seems rainy because you listen to it in winter does not mislead). Like the Day of week and Season fields, they describe an item’s typical plays, not every one."),
                .paragraph("**When it downloads.** Weather is topped up when a sync finishes and shortly after the app opens, at most every 15 minutes, and straight away when you turn weather on, choose a place or change a trip (**Update Now** in Settings › Weather does it whenever you like). A top-up asks only for the days since the last one, so it is a request or two. A play from the last hour or so can therefore show no weather until the next top-up; it is never guessed, and it never matches a weather filter until it has some."),
                .paragraph("**Counting only rainy or snowy plays.** In [Query](help://query-basics), **Scope & limit › Only count plays at certain times or in certain weather** has an **In this weather** group of chips (Rain, Snow, Fog, Storm, Clear, Cloudy) and a **how warm it was** group (Cold, Mild, Hot). With **Snow** and **Cold** ticked, the query counts only plays made in cold, snowy hours, so “my most played songs in the rain” is the top of a list of rainy plays, not of songs that merely have some. It combines with the days, months and hours chips (“winter Sunday mornings in the snow”). **In this city**, **In this state or region** and **In this country** work the same way for places: they list your home place’s and each trip’s city, state or region and country (a state or country only where the place has one), and count only the plays made there, so “top 25 songs I listened to in Germany” is a query away. The **City** and **Cities played in** fields describe an item instead: the city most of its plays were made in, and how many different cities it was played in."),
                .callout(.tip, "Weather follows the seasons, so a plain “most played when cold” is mostly “most played in winter”. Use **Weather lift**, which compares with the same period’s overall plays, and a minimum number of plays so a handful of plays can’t dominate."),
                .paragraph("**On a track’s page** each play in its list shows the place and the weather at that hour, and an artist or album page has a Weather tile for what it leans into (see [Artist, album and track pages](help://screen-detail-pages)). The **Scrobble History** page (Overview › Most recent › View all) shows each scrobble’s place and weather too, in a wide enough window."),
                .paragraph("**In Trends.** The **Weather & places** group has six cards. Three are new: **Leaning into the weather** ranks the artists, albums or tracks you play more (or less) than usual in a chosen weather (Rain, Snow, Cold, Hot, Clear or Cloudy), season-adjusted like the rest and only when the difference is 15% or more, with enough plays (40+ with weather, 8+ in that weather) on at least four different days, so one long rainy sitting is not mistaken for a pattern; click a row to open exactly those plays in Query. **Artist weather map** puts artists on a map of weather (Clear, Cloudy, Fog, Rain, Snow, Thunderstorm; a kind with under 30 plays gets no row) down the side against temperature across the bottom, in your temperature unit. A bubble is the artist’s picture (a plain dot when the app has none, or when the bubble is too small to recognise anyone in, as happens at Top 50 and 100); its size is the artist’s plays, its ring is how strongly it leans there against the other artists shown (pale gold for the weakest lean on the map to deep red-orange for the strongest, with the range on the key under the chart; blue for less than usual in Most played), and the shading behind is how much you listened in that weather and temperature. **Weather affinity** puts the artists that lean furthest into one weather and temperature, each where it leans (and no one cell takes more than a quarter of the map, so it spreads out; cells nobody leans into stay empty); **Most played** puts the artists you play most, each where it is played most. An artist leans only with 30+ plays with weather, 8+ of them in that cell on four or more different days, 25% or more above usual and clearly more than luck would give, so the quiet corners of the map are honest rather than filled. Temperature is where you were: trips count with the weather there. **Top 10 / 25 / 50 / 100** sets how many are shown (10 to start); the temperature axis leaves off only the hottest and coldest ranges you never listened in. Hover a bubble for its plays across the kinds of weather against how all your plays are spread; click it to open exactly those plays in Query. **Where you listened** puts each trip next to home: plays a day against your home rate, new artists first heard there, the weather and your top artists, over a chart of plays a day in which each place you went to is shaded in its own colour, the same for every trip to the same city (named above the chart where there is room, and matching the dot in front of its row); the **City / State/Region / Country** switch above it groups trips to the same state or country into one colour, one name and one row (“Germany · 3 trips · 18 days”) with the plays, days, new artists, weather and top artists added together, so repeat trips to a place read as one; the region and country come from the place you chose when you added the trip (a place you entered as coordinates or only typed a name for has none and stays on its own at every level; a place with a country but no region is listed under its country at State/Region); click a trip or group to open its plays. The card shows 8 trips; **All trips…** opens the full list in [Tools › Trips](help://tool-trips). With weather off the card still appears, without the weather columns. A day counts as a trip day when the trip covers its middle. The other three show your listening against the weather where you were (home, or a trip): **Weather and listening** (a tile for each kind of weather with how much more or less than an average day you listen in it, such as +23% in rain), **Temperature and time of day** (a grid of how much more or less than usual you play at each temperature, from your coldest to your warmest hours, in each part of the day) and **Listening against the weather** (each week’s scrobbles over the weather of that week, drawn on a background that runs from blue for cold weeks to red for warm ones, with dots for rainy and snowy weeks; for a period under about five months it shows days). The bars and percentages are per day *of that weather*, so more plays on clear days just because there are more clear days never counts as liking them. **Allow for the time of year** (on by default) compares each hour with your usual listening in the same month, which stops cold weather standing in for winter. A weather with too few plays (under 30) is faded and says so, and a grid cell with under 20 plays is left blank. Hover for the numbers; click a tile, a cell or a week to open exactly those plays in Query (as artists, albums or tracks, as you choose). With a comparison period each tile also says what it was before. The Metric switch counts scrobbles or time listened."),
                .paragraph("**Privacy.** Turning weather on sends Open-Meteo your home place’s rounded coordinates and date ranges (and each trip’s place and dates: Open-Meteo sees where and when, never who) (and the name you type when searching for a city). It never sends what you listened to, and the weather is kept on this Mac (never in a backup, since it can be downloaded again). **Remove Downloaded Weather** deletes it; **Offline mode** stops the downloads. See [What leaves your Mac](help://what-leaves-your-mac)."),
                .paragraph("Weather data by [Open-Meteo.com](https://open-meteo.com/)."),
            ]
        ),
        HelpArticle(
            id: "screen-sharing",
            title: "Sharing",
            summary: "The Share button: an image or text of what you are looking at, for friends or a Reddit post.",
            blocks: [
                .paragraph("A **Share** button appears where something worth showing is: on [Top Charts](help://screen-top-charts), and on the header of an artist, album or track page ([how](help://screen-detail-pages)), on [Milestones](help://screen-milestones), on each month of the [Timeline](help://screen-timeline), on the results of a [Query or Ask](help://query-basics), on a goal in [Goals](help://tool-goals) (on its page, and on its card in the list), on a [Rabbit Hole](help://tool-rabbit-hole) path, on each chart of [Trends](help://screen-trends), and on [Overview](help://screen-overview), where **Share** (top right) makes a listening recap of the period shown. The [Collage Generator](help://tool-collage) has **Copy Image** and **Share…** beside Save PNG. The button opens a preview of a card made from exactly what is on screen, with options that suit that card (size, how many rows, whether to show the numbers and movement) and four ways to send it on. On every card you can type your own **title** and **subtitle** (blank keeps the card’s own)."),
                .bullets([
                    "**Copy Image** puts the card on the clipboard. Paste it into a Reddit post, a message or a document.",
                    "**Save PNG…** saves it as a file (twice the card’s size, so it stays sharp when shrunk).",
                    "**Share…** opens the macOS Share menu (Messages, Mail, AirDrop, Notes and so on).",
                    "**Copy Text** copies the same list as a Markdown table (Reddit shows it as a table), a Markdown list, or plain text.",
                ]),
                .paragraph("A chart makes a ranked list. An artist, album or track page makes a profile card: the picture and name, the page’s own numbers as tiles (the plays or time in the page’s period, first and last scrobble, play frequency, and the page’s facts such as release date and turnover), the yearly rank and milestone badges, and the trend line. The card says the period the page is showing. The text forms give the same numbers as a table or list."),
                .paragraph("A list that isn’t a ranking (the milestones you reached) has no row numbers, and shows each milestone as a coloured pill like the Milestones page. The library’s own total milestones have no picture, so the preview lets you choose a trophy or the Last.fm logo for them. A month of the Timeline makes a recap card: its name, totals, its top artist, album and track with their pictures, and the milestones reached that month. One achieved milestone makes a card with the number reached, the date and how long it took. The Overview recap has the period as its title, the totals the page shows (scrobbles, or time listened when that is the Metric, then artists, albums and tracks), the change in scrobbles against the comparison you chose (left out when none applies, and for **All time**, which has nothing to compare with, it says when you started scrobbling instead), new artists, scrobbles per day, your current streak, and your top artist, album and track; how many tiles show depends on the card’s size. When the Metric is time listened the card waits until the track lengths are known. A Trends chart makes a chart card (see **Chart cards** below). A query’s results make a list card with one value column (the one it is sorted on, or the one you pick in the preview) and all the columns in the text copies."),
                .heading("Chart cards"),
                .paragraph("A Trends chart is drawn for the card itself, at the card’s size, rather than photographed from the window: the text is larger, the chart fills the space, and the controls and hover hints are left off. Each card has the period and your title above it, a sentence about what the chart shows (for example “Busiest: Thursday 12 PM · 54 scrobbles”, “Rain is your music weather: +23% against an average day” or “Away you play 31% as much as at home”), the chart, and, if you turn it on, a line on how the numbers were worked out. Each chart opens on the shape that suits it (wide for the time charts, square for the tiles and quadrants, portrait for the ranked lists), and you can change it. Eras drawn **By release year** is still a picture of the chart, shaped to it so it has no empty band; the preview’s **Shape the card to the chart** switch turns that off to choose a size."),
                .paragraph("Every card can be edited: type your own **title**, **subtitle** and, on a chart, **caption** in the preview (leave one blank to keep the written one, or turn the caption off). What you type belongs to that one share and isn’t remembered; the choices below are, per kind of card."),
                .bullets([
                    "**Include the comparison with the previous period** is on every chart that compares, and is off until you turn it on. It adds the comparison to the chart (the previous line, grid, river, tick or change figure), to the sentence and to the “Compared with …” line under the title, and to the text copy.",
                    "**Weather and listening:** leave out weathers with too few plays, the plays and hours under each tile. **Temperature and time of day:** the percentages in the cells and the colour key. **Listening against the weather:** the temperature colours, the rain and snow markers, the average line and the key.",
                    "**Leaning into the weather:** 3 to 10 rows, the artwork, the plays and days behind each, and the bars. **Artist weather map:** how many artists, the artwork, their names, the shading and the key. **Where you listened:** the chart, 1 to 8 trips, the home row, new artists, the weather and the top artists (it follows the City / State/Region / Country switch on the page).",
                    "**Volume over time:** per period or running total, and the shading under the line. **When you listen:** the hour labels and the key. **Discovery** and **Eras:** the key. **Rankings:** 3 to 10 lines, naming the lines and the points. **Long tail:** the min, max, mean, median and mode figures.",
                    "**Taste:** 3 to 15 tags and the bars. **Loyalty** (drawn as its four groups, each with its count and top names): how many names and what each group means. **Listening flow** (drawn as the strongest hand-offs): 3 to 10 hand-offs and the bars.",
                    "**A goal** is dressed like its card in the app: the percentage heard, the progress bar with its tick for where the plan would have you today, the status in its colour (green ahead, orange behind, red past the deadline), the figures, and the burn-down with its fill, the on-target line, today, the deadline and (from the goal’s own page) the forecasts. An achieved goal is gold, with a gold rim, the date it was finished and how many days early. **Show the caption** adds a sentence saying where it stands (“169 of 218 loved tracks heard (78%): 49 to go, 64 days left. 18 behind plan.”), which is off for a goal because the card already says it. You can leave out the on-target line, the forecasts and the key, and show the range around each forecast. From a card in the list, the share has no forecasts; open the goal to share them.",
                    "**Show the caption** and **Show how it’s worked out** are on every chart card. **Copy Text** gives the title, the sentence and the chart’s lines (the rows or the figures it shows) as a Markdown list, a table or plain text.",
                ]),
                .paragraph("Cards are square, portrait or wide. The card uses the pictures saved on this Mac; with [Offline mode](help://offline-mode) on, a picture that isn’t saved is left out and the preview says so."),
                .heading("What a card says about you"),
                .paragraph("Nothing by default: no Last.fm name and no “Scroblytics” credit. Turn on **Show my Last.fm name** (from your saved account) or **Show “Scroblytics” on the card** in the preview, or under Settings › General › Sharing; your choice is remembered. With your name on, **Include my profile picture** adds your Last.fm profile picture, as a circle, in front of it (the Collage Generator has the same choice as **My picture**). The picture is asked of Last.fm the first time you use it, then kept on this Mac and refreshed about once a week; with Offline mode on, or if Last.fm can’t be reached, a card uses the saved picture or goes without one, and says so in the preview. In front of your name goes the Last.fm logo (the red circle) by default; Settings › General › Sharing also offers the “last.fm” wordmark, a simple badge, or no mark at all, and the same choice marks the Now Playing bar. A card is made on your Mac. Nothing is sent anywhere unless you paste it or pick a target in the Share menu, and no Reddit or other account is used."),
            ]
        ),
        HelpArticle(
            id: "screen-library",
            title: "Library",
            summary: "An A–Z browser of artists and albums.",
            blocks: [
                .paragraph("Library lists **artists** or **albums** alphabetically (a leading “The” is ignored for sorting) with an A–Z jump strip, in grid or list form. It has no Tracks tab. Selecting an item opens its detail page."),
                .paragraph("It uses the same Period control as Top Charts: the list contains items that have plays in the selected range, so choose **All time** to see everything. It shows no rank or play count; use [Top Charts](help://screen-top-charts) for those."),
            ]
        ),
        HelpArticle(
            id: "screen-detail-pages",
            title: "Artist, album and track pages",
            summary: "The stats and editing controls on a detail page.",
            blocks: [
                .paragraph("Each page is one card with the artwork, name, trend line, the numbers below, and the tags, then the item’s own list: an artist’s albums or tracks, an album’s tracks, or a track’s plays. Facts that are still being looked up show “Checking…” in place, so the layout doesn’t jump."),
                .definitions([
                    HelpDefinition(term: "Stat tiles", detail: "Scrobbles (or Time listened) in the range, First scrobble and Last scrobble, and **Play frequency**: average days between plays across the item’s whole lifetime = (last − first) ÷ (plays − 1), blank with fewer than two plays."),
                    HelpDefinition(term: "Yearly medals", detail: "“#N · YYYY”: the item’s rank among everything of its kind in each past calendar year, for years it placed in the top 25. The current year isn’t included."),
                    HelpDefinition(term: "Milestones", detail: "Upcoming and achieved play-count [milestones](help://metrics-milestones) for this item."),
                    HelpDefinition(term: "Release date and duration", detail: "The pencil opens an editor. A release date accepts `YYYY`, `YYYY-MM` or `YYYY-MM-DD`; a duration accepts `m:ss` or `h:mm:ss`, with an Apple Music prefill. “Reset to Detected” removes your override. A track’s own release date applies to that song only, not its album."),
                    HelpDefinition(term: "Tempo", detail: "A track’s tempo in BPM, with its time signature and key when GetSongBPM knew them; hover for where it came from. The pencil opens an editor with ÷ 2 and × 2 buttons for a tempo a detector reported at half or double speed. “Reset to Detected” removes your correction. See [Tempo](help://tempo-lookup)."),
                    HelpDefinition(term: "Share", detail: "The share icon beside the name makes a card of the page (see [Sharing](help://screen-sharing)): the picture, the numbers in the tiles, the badges and the trend, for the period chosen above. It is disabled until the numbers have loaded. When [weather](help://screen-weather) says what this is played in more than usual (the Weather tile), the preview has **Include the weather it’s played in**, off unless you turn it on; a track qualifies on the same terms as an artist or album, so one with few plays has none."),
                    HelpDefinition(term: "Weather tile", detail: "With [weather](help://screen-weather) turned on and downloaded, an artist or album page has a **Weather** tile in the header saying what weather it is played in more than usual, such as “Rain +34%” (or “Cold +21%”, for how warm it was): its share of plays in that weather against the share across all your plays in the period shown. It needs at least 20 plays with weather, and the weather in at least 5 of them; with nothing standing out by at least 15% it says “No standout”, and with too little data there is no tile."),
                    HelpDefinition(term: "Plays list and weather", detail: "A track’s plays are listed newest first with the date, album and time. With [weather](help://screen-weather) turned on and downloaded, each play also shows a **Location** (your home place) and the **Weather** at that hour, such as “Rain · 8 °C” with an icon, in the unit chosen in Settings › Weather. Location is the trip’s place for plays made on a trip, and a dash means there is no weather for that time yet, for example before the first year downloaded."),
                    HelpDefinition(term: "Tags", detail: "Community tags (from Last.fm, read-only) and Your tags. Adding or removing yours needs [Track Actions](help://track-actions) and changes your public Last.fm profile."),
                    HelpDefinition(term: "Album turnover", detail: "Cycles completed, rate and tracks still unheard ([how](help://metrics-turnover)). They show as tiles (**Tracks**, **Turnover**, **Full cycles** and **This cycle**, such as “8 of 11”), and the per-track checklist is the **Cycle** column of the track table."),
                    HelpDefinition(term: "Track table", detail: "An album’s whole tracklist in order, with each track’s plays in the chosen period and when it was last played. The **Cycle** column shows whether the track counts toward the current listen-through, which is all-time, not limited to the period. A track with no plays in the period is dimmed and shows 0, but it still opens its own page (which shows its plays for whatever period you choose). Plays that match no title on the tracklist are listed under “Other tracks played”. **All tracks**, **Played in period** and **Not heard this cycle** filter it. With no Last.fm account, no tracklist or no match, it is just the tracks you played, with no Cycle column. The playlist export includes only tracks you played. **Length** is the track’s saved length (your correction, else the lookup); a track whose length isn’t known shows a dash. A narrow window drops “Last played” first, then “Length”."),
                    HelpDefinition(term: "Sort and direction", detail: "The **Sort** menu orders an album’s tracks or an artist’s albums and tracks, and the arrow beside it reverses the order; its tooltip says which way it runs (“Newest first”, “Z to A”). Track order and A–Z start upward; plays and dates start with the most or newest. Choosing another sort resets the direction. Where a track or album has nothing to date (no release year, no play in the period), it stays last either way."),
                    HelpDefinition(term: "Fix album match…", detail: "Choose which tracklist an album should be compared with. Tapping a candidate only stages it; **Save** commits. Options: a Last.fm alternate, an edition from your Music library, a pasted tracklist, “just use the tracks I’ve played”, or reset to automatic. The decision applies to all name variants of the album and is included in backups. When an album has more than one edition name, the sheet also offers **Count this edition on its own**: use it for an edition with extra discs or different tracks (an anniversary edition, say). Its plays, Last.fm tracklist and turnover are then counted apart from the other editions, and turning it off merges them again. Until then the **Turnover** tile says “Counted with all editions”. The Missing Data field **Merged Editions** finds the names worth doing this for; merging an edition back counts as having reviewed it. Use the pencil on the **Turnover** tile (a warning when the match is uncertain), or right-click the album art."),
                ]),
            ]
        ),
        HelpArticle(
            id: "screen-timeline",
            title: "Timeline",
            summary: "Your top artist, album and track for every month and week.",
            blocks: [
                .paragraph("Newest month first. Each month shows totals (plays, artists, albums, tracks), any milestone badges reached that month, and the top artist, album and track; its weeks (starting on your chosen week-start day) are nested beneath. The only control is the Metric. It ignores the date range. Each month has a **Share** button that makes a recap card of it ([Sharing](help://screen-sharing))."),
                .paragraph("A period’s winner is the highest value; ties go to whichever was first played in that period, then to artist name. Artist spellings are combined; albums are identified by exact artist and album name."),
            ]
        ),
        HelpArticle(
            id: "screen-trends",
            title: "Trends",
            summary: "Charts about how your listening changes and is distributed.",
            blocks: [
                .paragraph("Trends has its own Period and **Compare with** control (see [Date range, comparison and Metric](help://concepts-metric-compare)) and five groups, chosen with **Show**. Each chart has its own Metric switch, and clicking part of a chart opens Query pre-filled. Query’s breadcrumb and Back button return to the Trends screen that opened it. Each chart has a **Share** button beside its title that makes a card of the chart, drawn for the card itself at the card’s size (not a picture of the window): larger text, the chart filling the space, and a sentence about what it shows that you can retype or turn off. Each chart offers what makes sense to include: for example the key, the points or the figures on the line and bar charts, and **Include the comparison with the previous period**, which is off unless you turn it on and then adds the comparison to the chart, the sentence and the line under the title; the artwork, plays and days on Leaning into the weather; the chart, the home row, new artists, weather and top artists on Where you listened; how many rows on the ranked lists (Rankings, Taste, Listening flow, Leaning into the weather). **Show how it’s worked out** adds a line on the method. Eras drawn **By release year** is still a picture of the chart, shaped to it so it is as large as it can be with no empty band (turn off **Shape the card to the chart** in the preview to choose Square, Portrait or Wide instead) ([Sharing](help://screen-sharing)); a chart that shows only a “not enough data” message has nothing to share."),
                .table(headers: ["Group", "Charts"], rows: [
                    ["**Listening**", "Volume over time; When you listen (weekday × hour heatmap); Discovery (new vs repeat plays) — [Discovery](help://metrics-distribution)"],
                    ["**Weather & places**", "Weather and listening; Leaning into the weather; Artist weather map; Temperature and time of day; Listening against the weather; Where you listened — six cards, once [weather is turned on](help://screen-weather)"],
                    ["**Taste & eras**", "Eras (share by release decade); Taste (top tags) — [Eras and Taste](help://metrics-trends-other)"],
                    ["**Habits**", "Long tail; Loyalty — [Long tail and Loyalty](help://metrics-distribution)"],
                    ["**Rankings & flow**", "Rankings (bump chart); Listening flow — [Rankings and Flow](help://metrics-trends-other)"],
                ]),
            ]
        ),
        HelpArticle(
            id: "screen-milestones",
            title: "Milestones",
            summary: "Upcoming and achieved play-count milestones.",
            blocks: [
                .paragraph("Pick Total, Artists, Albums or Tracks, then filter by tier (100 up to 10K, and a combined 25K+ chip). **Upcoming** shows progress to the next threshold, “N to go” and an estimated date based on your last 30 days (up to 60 per category); **Achieved** shows when each threshold was crossed. It covers all of your history and ignores the date range. Definitions: [Milestones](help://metrics-milestones). **Share** (top right) makes a list card of the achieved milestones for the category and tier you are looking at; the share icon on an achieved card makes a card for that one milestone ([Sharing](help://screen-sharing))."),
            ]
        ),
        HelpArticle(
            id: "screen-search-now-playing",
            title: "Search and Now Playing",
            summary: "Library search and the Now Playing shelf.",
            blocks: [
                .bullets([
                    "**Search Library… (⌘F or the toolbar magnifier)** searches artists, albums and tracks across your whole history, ranking exact matches first and then by all-time plays. Choosing a result opens it in Library.",
                    "**Now Playing** shows your current Last.fm track in a shelf at the bottom while one is playing, with a Hide button; the Last.fm mark at its right end is the one chosen in Settings › General › Sharing. **View › Show Now Playing** hides or shows it. The app checks about every 15 seconds while a window is active, backing off up to 2 minutes after failures. Hiding the shelf also stops the checking, and showing it again resumes it. [Offline mode](help://offline-mode) stops it too. The playing track is never saved as a scrobble.",
                    "**Back to Overview** appears in the toolbar after you jump from an Overview card, to return you to it.",
                ]),
            ]
        ),
    ])
